// ============================================================================
// 3. SOUND SYNTHESIZER (WEB AUDIO API - ZERO EXTERNAL ASSETS)
// ============================================================================
class SoundEngine {
  constructor() {
    this.ctx = null;
    this.enabled = true;
  }

  init() {
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) {
        this.ctx = new AudioCtx();
      }
    }
    if (this.ctx && this.ctx.state === "suspended") {
      this.ctx.resume();
    }
  }

  playTone(freq, type = "sine", duration = 0.15, gainVal = 0.15, startTimeOffset = 0) {
    if (!this.enabled) return;
    this.init();
    if (!this.ctx) return;

    try {
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      const now = this.ctx.currentTime + startTimeOffset;

      osc.type = type;
      osc.frequency.setValueAtTime(freq, now);

      gain.gain.setValueAtTime(gainVal, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + duration);

      osc.connect(gain);
      gain.connect(this.ctx.destination);

      osc.start(now);
      osc.stop(now + duration);
    } catch (e) {
      console.warn("Audio error:", e);
    }
  }

  correct() {
    if (!this.enabled) return;
    this.playTone(523.25, "triangle", 0.25, 0.18, 0);
    this.playTone(659.25, "triangle", 0.25, 0.18, 0.08);
    this.playTone(783.99, "triangle", 0.25, 0.18, 0.16);
    this.playTone(1046.50, "sine", 0.35, 0.22, 0.24);
  }

  incorrect() {
    if (!this.enabled) return;
    this.playTone(220, "sawtooth", 0.18, 0.15, 0);
    this.playTone(174.61, "sine", 0.25, 0.15, 0.1);
  }

  magicSpark() {
    if (!this.enabled) return;
    [1046, 1318, 1567, 2093].forEach((f, i) => {
      this.playTone(f, "sine", 0.15, 0.1, i * 0.05);
    });
  }

  coin() {
    if (!this.enabled) return;
    this.playTone(987.77, "sine", 0.1, 0.15, 0);
    this.playTone(1318.51, "sine", 0.2, 0.18, 0.08);
  }

  combo() {
    if (!this.enabled) return;
    this.playTone(440, "triangle", 0.1, 0.15, 0);
    this.playTone(554.37, "triangle", 0.1, 0.15, 0.06);
    this.playTone(659.25, "triangle", 0.1, 0.15, 0.12);
    this.playTone(880, "sine", 0.25, 0.2, 0.18);
  }

  click() {
    if (!this.enabled) return;
    this.playTone(600, "sine", 0.05, 0.08, 0);
  }

  fanfare() {
    if (!this.enabled) return;
    const notes = [523.25, 659.25, 783.99, 1046.50, 1318.51];
    notes.forEach((note, idx) => {
      this.playTone(note, "triangle", 0.35, 0.2, idx * 0.1);
    });
  }

  tick() {
    if (!this.enabled) return;
    this.playTone(880, "sine", 0.04, 0.05, 0);
  }
}

