// ============================================================================
// 5. LOCAL STORAGE & PERSISTENCE
// ============================================================================
const Storage = {
  SAVES_KEY: "SOYLEYTIN_KEYIPKERLER_SAVES",
  RECORDS_KEY: "SOYLEYTIN_KEYIPKERLER_RECORDS",
  VIDEO_SEEN_KEY: "SOYLEYTIN_KEYIPKERLER_VIDEO_SEEN",

  getSaves() {
    try { return JSON.parse(localStorage.getItem(this.SAVES_KEY) || "[]"); } catch (e) { return []; }
  },

  saveGame(saveObj) {
    try {
      const saves = this.getSaves();
      saves.unshift({
        id: "save_" + Date.now(),
        date: new Date().toLocaleString("kk-KZ"),
        ...saveObj
      });
      localStorage.setItem(this.SAVES_KEY, JSON.stringify(saves.slice(0, 10)));
    } catch (e) { console.warn("Save error:", e); }
  },

  getRecords() {
    try { return JSON.parse(localStorage.getItem(this.RECORDS_KEY) || "[]"); } catch (e) { return []; }
  },

  addRecord(recordObj) {
    try {
      const records = this.getRecords();
      records.push({
        id: "rec_" + Date.now(),
        date: new Date().toLocaleDateString("kk-KZ"),
        ...recordObj
      });
      records.sort((a, b) => b.coins - a.coins || b.score - a.score);
      localStorage.setItem(this.RECORDS_KEY, JSON.stringify(records.slice(0, 15)));
    } catch (e) { console.warn("Record error:", e); }
  },

  hasWatchedVideo(charKey) {
    try {
      const seen = JSON.parse(localStorage.getItem(this.VIDEO_SEEN_KEY) || "{}");
      return !!seen[charKey];
    } catch (e) { return false; }
  },

  setWatchedVideo(charKey) {
    try {
      const seen = JSON.parse(localStorage.getItem(this.VIDEO_SEEN_KEY) || "{}");
      seen[charKey] = true;
      localStorage.setItem(this.VIDEO_SEEN_KEY, JSON.stringify(seen));
    } catch (e) {}
  },

  clearAll() {
    localStorage.removeItem(this.SAVES_KEY);
    localStorage.removeItem(this.RECORDS_KEY);
    localStorage.removeItem(this.VIDEO_SEEN_KEY);
  }
};

